((SELECT id FROM m), 'Lunch & Dinner - Appetizers', 0, 'Boneless Wings', 'Tender, juicy nuggets of breast meat breaded and fried. Served with a choice of dipping sauce.', '$12.00', 12.00, ARRAY[]::text[], 0),
((SELECT id FROM m), 'Lunch & Dinner - Appetizers', 0, 'Voodoo Shrimp', 'Fried shrimp served with a sweet and spicy sauce.', '$13.00', 13.00, ARRAY[]::text[], 1),
((SELECT id FROM m), 'Lunch & Dinner - Appetizers', 0, 'Fried Pickle Chips', 'Breaded and served with ranch.', '$12.00', 12.00, ARRAY[]::text[], 2),
((SELECT id FROM m), 'Lunch & Dinner - Appetizers', 0, 'Onion Rings', 'Lightly floured thin-cut rings fried and served with ranch.', '$10.00', 10.00, ARRAY[]::text[], 3),
((SELECT id FROM m), 'Lunch & Dinner - Appetizers', 0, 'Wings', 'Tossed in your favorite wing sauce with a complimentary ranch or blue cheese dressing. Celery available upon request. Wing Sauce Choices: **NEW** Ghost Buffalo, **NEW** Spicy BBQ, **NEW** Spicy Garlic Teriyaki, **NEW** Lemon Pepper Dry Rub, Buffalo, BBQ, Sweet N'' Spicy Gochujang, Carolina Mustard, Dry Rub, Asian Sting, Spicy Garlic Teriyaki', '$16.00', 16.00, ARRAY[]::text[], 4),
((SELECT id FROM m), 'Lunch & Dinner - Appetizers', 0, 'Jalapeño Popper Deviled Eggs', 'Whipped egg yolks mixed with mayonnaise, mustard, onion, bacon, sriracha, pepper jack cheese, and diced jalapeños piped into the whites with a dash of cayenne pepper.', '$8.00', 8.00, ARRAY[]::text[], 5),
((SELECT id FROM m), 'Lunch & Dinner - Appetizers', 0, 'Southwestern Egg Rolls', 'Pulled chicken, black beans, corn, chipotle peppers, and southwestern rice, rolled and fried. Served with a chipotle ranch dipping sauce.', '$12.00', 12.00, ARRAY[]::text[], 6),
((SELECT id FROM m), 'Lunch & Dinner - Appetizers', 0, 'Nachos', 'Loaded nachos with your choice of chicken or seasoned ground beef, plus black beans, jalapenos, banana peppers, corn, and smothered in queso. Pico de gallo, fresh guacamole, sour cream, and housemade salsa served on the side.', '$15.00/+', 15.00, ARRAY[]::text[], 7),
((SELECT id FROM m), 'Lunch & Dinner - Appetizers', 0, 'Chips & Queso', 'Fresh corn tortilla chips served with warm queso dip and salsa.', '$10.00/+', 10.00, ARRAY[]::text[], 8),
((SELECT id FROM m), 'Lunch & Dinner - Appetizers', 0, 'Chips & Guacamole', 'Fresh corn tortilla chips served with fresh guacamole and salsa', '$12.00', 12.00, ARRAY[]::text[], 9),
((SELECT id FROM m), 'Lunch & Dinner - Appetizers', 0, 'Chicken Gizzards', 'Basket of seasoned gizzards breaded and fried crispy. Served with buffalo sauce', '$12.00', 12.00, ARRAY[]::text[], 10),
((SELECT id FROM m), 'Lunch & Dinner - Appetizers', 0, 'Cheese Curds', 'White cheese curds fried with marinara and ranch.', '$12.00', 12.00, ARRAY[]::text[], 11),
((SELECT id FROM m), 'Lunch & Dinner - Sandwiches & Burgers', 1, 'Nashville Hot Chicken Sliders', 'Sweet and spicy fried chicken with sliced dill pickles on brioche slider buns. Also available with grilled chicken. 2 sliders for $13 or 3 sliders for $16.', '$13.00/+', 13.00, ARRAY[]::text[], 12),
((SELECT id FROM m), 'Lunch & Dinner - Sandwiches & Burgers', 1, 'Classic Chicken Sandwich', 'Hand breaded fried chicken breast with lettuce and tomato. Make it Nashville or Iowa Hot for $1.', '$14.00', 14.00, ARRAY[]::text[], 13),
((SELECT id FROM m), 'Lunch & Dinner - Sandwiches & Burgers', 1, 'Chicken Bacon Ranch', 'Grilled chicken breast topped with swiss cheese and two strips of bacon. Substitute fried chicken for $1.', '$15.00', 15.00, ARRAY[]::text[], 14),
((SELECT id FROM m), 'Lunch & Dinner - Sandwiches & Burgers', 1, 'Grinder Po'' Boy', 'Traditional Graziano''s Italian grinder meat cooked with onions and poblano peppers, then stuffed in a french roll and topped with melted provolone cheese.', '$13.00', 13.00, ARRAY[]::text[], 15),
